"""EasyOCR adapter using the shared Latin model for Turkish and English."""

from __future__ import annotations

from importlib.metadata import version
import logging
from pathlib import Path

from virvision.perception.base import ProviderInfo, RawText
from virvision.perception.device import resolve_device, synchronize

from .common import artifact

LOG = logging.getLogger("virvision.perception")


class EasyOCRProvider:
    def __init__(
        self,
        *,
        languages: tuple[str, ...] = ("tr", "en"),
        device: str = "auto",
        model_storage_directory: str | None = None,
        download_enabled: bool = True,
        detector_network: str = "craft",
        min_confidence: float = 0.0,
    ):
        self.languages = tuple(languages)
        self.requested_device = device
        self.model_storage_directory = (
            Path(model_storage_directory).expanduser().resolve()
            if model_storage_directory is not None
            else None
        )
        self.download_enabled = download_enabled
        self.detector_network = detector_network
        self.min_confidence = min_confidence
        self._reader = None
        self._device = "unresolved"
        self._model_name = f"{detector_network}+latin_g2"

    @property
    def info(self) -> ProviderInfo:
        artifacts = ()
        if self.model_storage_directory is not None and self.model_storage_directory.is_dir():
            paths = sorted(
                path
                for path in self.model_storage_directory.iterdir()
                if path.is_file() and path.suffix.lower() in {".pth", ".pt"}
            )
            artifacts = tuple(artifact(path) for path in paths)
        return ProviderInfo(
            "easyocr",
            self._model_name,
            self.requested_device,
            self._device,
            version("easyocr"),
            artifacts,
        )

    def load(self) -> None:
        if self._reader is not None:
            return
        try:
            import easyocr
        except ImportError as exc:
            raise ImportError(
                'EasyOCR is unavailable. Install with: pip install -e ".[vision]"'
            ) from exc
        self._device = resolve_device(self.requested_device)
        if self.model_storage_directory is not None:
            self.model_storage_directory.mkdir(parents=True, exist_ok=True)
        self._reader = easyocr.Reader(
            list(self.languages),
            gpu=self._device.startswith("cuda"),
            model_storage_directory=(
                str(self.model_storage_directory)
                if self.model_storage_directory is not None
                else None
            ),
            download_enabled=self.download_enabled,
            detect_network=self.detector_network,
            verbose=False,
        )
        LOG.info(
            "OCR loaded: backend=easyocr model=%s languages=%s device=%s",
            self._model_name,
            ",".join(self.languages),
            self._device,
        )

    def extract(self, image) -> tuple[RawText, ...]:
        self.load()
        try:
            import numpy as np
        except ImportError as exc:
            raise ImportError("EasyOCR requires NumPy; reinstall vir-vision[vision]") from exc
        synchronize(self._device)
        results = self._reader.readtext(np.asarray(image.image), detail=1, paragraph=False)
        synchronize(self._device)
        rows = []
        for result in results:
            if not isinstance(result, (tuple, list)) or len(result) != 3:
                raise RuntimeError("EasyOCR returned an unexpected record")
            polygon, text, confidence = result
            confidence = float(confidence)
            if confidence < self.min_confidence:
                continue
            rows.append(
                RawText(
                    str(text),
                    confidence,
                    tuple((float(p[0]), float(p[1])) for p in polygon),
                    "unknown",
                )
            )
        return tuple(rows)
